const els={body:{className:""},app:{innerHTML:""},picker:{addEventListener(){}}};
global.location={search:""};
global.document={body:els.body,querySelector(s){return s==="#app"?els.app:els.picker},querySelectorAll(){return []},addEventListener(){}};

const P={tree:{name:'Greener Noida',type:'Tree plantation',place:'Sector 98 Â· Noida',count:24,score:92,summary:'Visible canopy growth across three monitored plots.',before:'https://images.unsplash.com/photo-1501004318641-b39e6451bec6?auto=format&fit=crop&w=1000&q=80',after:'https://images.unsplash.com/photo-1511497584788-876760111969?auto=format&fit=crop&w=1000&q=80',media:[['Seedling installation','18 Jun','https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?auto=format&fit=crop&w=700&q=80'],['Volunteers planting','22 Jun','https://images.unsplash.com/photo-1497250681960-ef046c08a56e?auto=format&fit=crop&w=700&q=80'],['Canopy follow-up','04 Jul','https://images.unsplash.com/photo-1473445361085-b9a07f55608b?auto=format&fit=crop&w=700&q=80']]},water:{name:'Blue Sites',type:'Water conservation',place:'Riverside district',count:18,score:89,summary:'A monitored channel reconnecting clean water access.',before:'https://images.unsplash.com/photo-1509391366360-2e959784a276?auto=format&fit=crop&w=1000&q=80',after:'https://images.unsplash.com/photo-1437482078695-73f5ca6c96e2?auto=format&fit=crop&w=1000&q=80',media:[['Tank inspection','11 Jun','https://images.unsplash.com/photo-1538300342682-cf57afb97285?auto=format&fit=crop&w=700&q=80'],['Water testing','14 Jun','https://images.unsplash.com/photo-1581093458791-9d42e3c2e4d8?auto=format&fit=crop&w=700&q=80'],['Channel progress','21 Jun','https://images.unsplash.com/photo-1509391366360-2e959784a276?auto=format&fit=crop&w=700&q=80']]},infra:{name:'Block 42 Renewal',type:'Infrastructure',place:'Sector 42 Â· Noida',count:31,score:94,summary:'A complete before-to-after record of a public facility upgrade.',before:'https://images.unsplash.com/photo-1503387762-592deb58ef4e?auto=format&fit=crop&w=1000&q=80',after:'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1000&q=80',media:[['Site marking','02 Jul','https://images.unsplash.com/photo-1503387762-592deb58ef4e?auto=format&fit=crop&w=700&q=80'],['Foundation work','09 Jul','https://images.unsplash.com/photo-1541888946425-d81bb19240f5?auto=format&fit=crop&w=700&q=80'],['Finished stage','28 Jul','https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=700&q=80']]}};
const keys=Object.keys(P);let current='journal',project=keys.includes(new URLSearchParams(location.search).get('project'))?new URLSearchParams(location.search).get('project'):'tree';const d=P[project];const top=(eyebrow='AI-powered impact evidence')=>`<header class="top"><div class="brand">IMPACT <em>MEDIA LAB</em></div><small class="muted">${eyebrow}</small><div class="top-actions"><select class="btn project-picker" aria-label="Project"><option value="tree" ${project==='tree'?'selected':''}>Tree plantation</option><option value="water" ${project==='water'?'selected':''}>Water conservation</option><option value="infra" ${project==='infra'?'selected':''}>Infrastructure</option></select><button class="btn primary" data-action="report">Generate report</button></div></header>`;const head=(n,t,s)=>`<div class="section-head"><div><div class="eyebrow">${n}</div><h2>${t}</h2></div><p class="muted">${s}</p></div>`;const media=m=>m.map(x=>`<figure class="media"><img src="${x[2]}" alt="${x[0]}"><figcaption>${x[0]}<span class="muted">${x[1]} Â· demo media</span></figcaption></figure>`).join('');function journal(){return `<div class="shell">${top()}<section class="journal-hero"><div><div class="eyebrow">Field journal / ${d.type}</div><h1>Make every field moment count.</h1><p class="muted">A calm, evidence-first workspace for teams turning raw media into a story they can stand behind.</p><div class="pills"><span class="tag">${d.place}</span><span class="tag">${d.count} assets</span><span class="tag">${d.score}% confidence</span></div></div><div class="journal-card"><div class="eyebrow">Active project</div><h2>${d.name}</h2><span class="tag">${d.type}</span><div class="stat-row"><div class="stat"><b>${d.count}</b><span>evidence assets</span></div><div class="stat"><b>${d.score}%</b><span>AI confidence</span></div><div class="stat"><b>3</b><span>moments found</span></div></div><p class="muted">${d.summary}</p></div></section><section class="journal-section">${head('01 / The story','Change you can point to.','Original media stays attached to every claim.') }<div class="story-grid"><div>${[['18 Jun','Baseline','The first field record gives reviewers a clear starting point.'],['22 Jun','Action','The AI groups activity, location, and people into one moment.'],['04 Jul','Follow-up','A later record makes visible change easy to inspect.']].map(x=>`<div class="story-step"><small>${x[0]}</small><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div><div class="evidence-collage">${d.media.map((x,i)=>`<figure><img src="${x[2]}" alt="${x[0]}"><figcaption>${x[0]} Â· ${x[1]}</figcaption></figure>`).join('')}</div></div></section><section class="journal-section">${head('02 / Visual evidence','Before â†’ after.','Cloudinary-derived views retain the original asset.') }<div class="compare"><figure><img src="${d.before}" alt="Before"><b>Before</b></figure><figure><img src="${d.after}" alt="After"><b>After</b></figure></div></section><section class="report-cta"><div><div class="eyebrow" style="color:var(--green)">Next step</div><h2>Turn the evidence into a review-ready report.</h2><p>Timeline, source links, AI findings, and confidence notes in one shareable view.</p></div><button class="btn" data-action="report">Create impact brief â†—</button></section></div>`}
function control(){const bars=[42,58,51,75,67,88,82,96,74,91,86,98];return `<div class="shell">${top('Live analysis workspace')}<div class="metric-strip"><div class="control-card"><b>${d.count}</b><span class="muted">assets ingested</span></div><div class="control-card"><b>98.2%</b><span class="muted">pipeline health</span></div><div class="control-card"><b>${d.score}%</b><span class="muted">model confidence</span></div><div class="control-card"><b>03</b><span class="muted">active locations</span></div></div><div class="control-grid"><section class="control-card"><div class="eyebrow">Media intelligence / live</div><h2>${d.name}</h2><p class="muted">${d.summary}</p><div class="signal">${bars.map(x=>`<i style="height:${x}%"></i>`).join('')}</div><div class="queue"><div><span>Vision analysis</span><span class="ok">Complete Â· 24/24</span></div><div><span>Timeline grouping</span><span class="ok">Complete Â· 3 moments</span></div><div><span>Source verification</span><span class="warn">Needs review Â· 2</span></div></div></section><section class="control-card"><div class="eyebrow">Workflow queue</div><h2>Evidence pipeline</h2><div class="queue"><div><span>Upload originals</span><span class="ok">Done</span></div><div><span>Generate previews</span><span class="ok">Done</span></div><div><span>Compare before / after</span><span class="ok">Done</span></div><div><span>Build report</span><span class="warn">Ready</span></div></div><button class="btn primary" data-action="report" style="margin-top:15px;width:100%">Run report builder</button></section></div><section class="control-card" style="margin-top:12px"><div class="eyebrow">Evidence ledger</div><h2>Source traceability</h2><table><thead><tr><th>Asset</th><th>Signal</th><th>Confidence</th><th>State</th></tr></thead><tbody><tr><td>north-001.jpg</td><td>Seedling installation</td><td>96%</td><td><span class="pill">verified</span></td></tr><tr><td>north-014.jpg</td><td>Community activity</td><td>91%</td><td><span class="pill">verified</span></td></tr><tr><td>east-008.jpg</td><td>Vegetation change</td><td>89%</td><td><span class="pill">review</span></td></tr></tbody></table></section></div>`}function card(){return `<div class="shell">${top('Impact story preview')}<section class="hero"><div><div class="eyebrow">${d.type} Â· ${d.place}</div><h1>Proof that the work changed the place.</h1><p>${d.summary} Every claim below links back to original media, AI analysis, and a point in time.</p><button class="btn" data-action="report" style="background:var(--green);border:0;color:var(--ink)">Open impact report â†—</button></div><div class="hero-art"></div></section><section class="kpis"><div class="kpi"><b>${d.count}</b><span>media assets</span></div><div class="kpi"><b>${d.score}%</b><span>AI confidence</span></div><div class="kpi"><b>3</b><span>verified moments</span></div></section><section class="card-grid"><article class="card-panel"><div class="eyebrow">01 / The change</div><h2>From bare site to living canopy.</h2><img src="${d.after}" alt="Project result"><p class="muted">Demo visual Â· original asset retained</p></article><article class="card-panel"><div class="eyebrow">02 / The evidence</div><h2>Three moments, one story.</h2><div class="mini-list">${d.media.map(x=>`<div class="mini"><i></i><div><strong>${x[0]}</strong><span>${x[1]} Â· linked to source</span></div></div>`).join('')}</div><button class="btn" data-action="report" style="margin-top:17px">View source ledger</button></article></section><p class="footer-note">Prototype only Â· demo media is used to show the product direction. Final submission should use credited field media.</p></div>`}function render(){document.body.className=current;document.querySelector('#app').innerHTML=current==='journal'?journal():current==='control'?control():card();document.querySelectorAll('[data-action=report]').forEach(b=>b.addEventListener('click',()=>{b.textContent='Report ready âœ“';b.classList.add('primary');setTimeout(()=>b.textContent=current==='control'?'Run report builder':current==='card'?'Open impact report â†—':'Create impact brief â†—',1100)}));document.querySelector('.project-picker').addEventListener('change',e=>{project=e.target.value;render()})}document.querySelectorAll('[data-pick]').forEach(b=>b.addEventListener('click',()=>{current=b.dataset.pick;document.querySelectorAll('[data-pick]').forEach(x=>x.classList.toggle('active',x===b));render()}));document.addEventListener('keydown',e=>{if(e.key!=='ArrowLeft'&&e.key!=='ArrowRight')return;const order=['journal','control','card'],i=order.indexOf(current);current=order[(i+(e.key==='ArrowRight'?1:-1)+order.length)%order.length];document.querySelectorAll('[data-pick]').forEach(x=>x.classList.toggle('active',x.dataset.pick===current));render()});render();

console.log('runtime ok', document.body.className, els.app.innerHTML.length);
